e":{"status":"observed","value":"メガ・コマンド・ドラゴン/革命軍"},"ability":{"status":"observed","value":"革命０トリガー：クリーチャーが自分を攻撃する時、自分のシールドが１つもなければ、このクリーチャーを手札から表向きにしてもよい。そうしたら、自分の山札の上から１枚を表向きにする。それが火の、進化ではないクリーチャーなら出し、このクリーチャーをその上に置く。\n進化：火のクリーチャー１体の上に置く。\n{3T} T・ブレイカー\nこのクリーチャーが出た時または攻撃する時、相手のクリーチャーを１体選んでもよい。その選んだクリーチャーとこのクリーチャーをバトルさせる。"},"image":{"status":"observed_source_url","value":"https://dm.takaratomy.co.jp/wp-content/card/cardimage/dm26ex5-002.jpg","downloaded":false,"verified":false}}]}}},{"official_card_id":"dm26ex5-003","official_url":"https://dm.takaratomy.co.jp/card/detail/?id=dm26ex5-003","card_number":"DM26EX5 3/40","canonical_id":84,"canonical_name":"百族の長 プチョヘンザ","cost":8,"cost_is_infinite":false,"civilizations":["light","nature"],"card_types":["クリーチャー"],"races":["ジュラシック・コマンド・ドラゴン","ダママ団","革命軍"],"power_text":"12500","power_value":12500,"checked_at":"2026-11-07T05:09:58.521Z","card_texts":["革命チェンジ：光または自然の、コスト５以上のドラゴン\n{3T} T・ブレイカー\n自分のマナゾーンにあるカードの枚数よりコストが小さい相手のクリーチャーは、タップして出る。\nファイナル革命：このクリーチャーが「革命チェンジ」によって出た時、そのターンに他の「ファイナル革命」を使っていなければ、このクリーチャーよりパワーが小さいクリーチャーをすべて持ち主のマナゾーンに置く。"],"source_metadata":{"official_catalog":{"verified":true,"official_url":"https://dm.takaratomy.co.jp/card/detail/?id=dm26ex5-003","checked_at":"2026-11-07T05:09:58.521Z","faces":[{"face":1,"type":{"status":"observed","value":"クリーチャー"},"civilization":{"status":"observed","value":"光/自然"},"rarity":{"status":"observed","value":"LEG"},"power":{"status":"observed","value":"12500"},"cost":{"status":"observed","value":"8"},"race":{"status":"observed","value":"ジュラシック・コマンド・ドラゴン/革命軍/ダママ団"},"ability":{"status":"observed","value":"革命チェンジ：光または自然の、コスト５以上のドラゴン\n{3T} T・ブレイカー\n自分のマナゾーンにあるカードの枚数よりコストが小さい相手のクリーチャーは、タップして出る。\nファイナル革命：このクリーチャーが「革命チェンジ」によって出た時、そのターンに他の「ファイナル革命」を使っていなければ、このクリーチャーよりパワーが小さいクリーチャーをすべて持ち主のマナゾーンに置く。"},"image":{"status":"observed_source_url","value":"https://dm.takaratomy.co.jp/wp-content/card/cardimage/dm26ex5-003.jpg","downloaded":false,"verified":false}}]}}},{"official_card_id":"dm26ex5-001","official_url":"https://dm.takaratomy.co.jp/card/detail/?id=dm26ex5-001","card_number":"DM26EX5 1/40","canonical_id":42,"canonical_name":"煌龍 サッヴァーク","cost":7,"cost_is_infinite":false,"civilizations":["light"],"card_types":["クリーチャー"],"races":["マスター・ドラゴン","メタリカ"],"power_text":"11000","power_value":11000,"checked_at":"2026-11-07T05:10:02.177Z","card_texts":["{D2W}ドラゴン・W・ブレイカー（このクリーチャーはシールドを２つブレイクする。各ブレイクの前に、自分の山札の上から１枚をシールド化するか、表向きにしてから自分のシールド１つの上に置く）\nこのクリーチャーが出た時、バトルゾーンにある相手のカードを１枚選び、表向きで持ち主のシールド１つの上に置く。\n自分のクリーチャーが離れる時、かわりにいずれかのシールドゾーンにある表向きのカードを１枚選び、持ち主の墓地に置いてもよい。"],"source_metadata":{"official_catalog":{"verified":true,"official_url":"https://dm.takaratomy.co.jp/card/detail/?id=dm26ex5-001","checked_at":"2026-11-07T05:10:02.177Z","faces":[{"face":1,"type":{"status":"observed","value":"クリーチャー"},"civilization":{"status":"observed","value":"光"},"rarity":{"status":"observed","value":"MDG"},"power":{"status":"observed","value":"11000"},"cost":{"status":"observed","value":"7"},"race":{"status":"observed","value":"マスター・ドラゴン/メタリカ"},"ability":{"status":"observed","value":"{D2W}ドラゴン・W・ブレイカー（このクリーチャーはシールドを２つブレイクする。各ブレイクの前に、自分の山札の上から１枚をシールド化するか、表向きにしてから自分のシールド１つの上に置く）\nこのクリーチャーが出た時、バトルゾーンにある相手のカードを１枚選び、表向きで持ち主のシールド１つの上に置く。\n自分のクリーチャーが離れる時、かわりにいずれかのシールドゾーンにある表向きのカードを１枚選び、持ち主の墓地に置いてもよい。"},"image":{"status":"observed_source_url","value":"https://dm.takaratomy.co.jp/wp-content/card/cardimage/dm26ex5-001.jpg","downloaded":false,"verified":false}}]}}}]'::jsonb) AS r(official_card_id text,official_url text,card_number text,canonical_id bigint,canonical_name text,cost smallint,cost_is_infinite boolean,civilizations text[],card_types text[],races text[],power_text text,power_value integer,checked_at timestamptz,card_texts text[],source_metadata jsonb);
DO $$ BEGIN
 IF (SELECT count(*) FROM public.tcg_games WHERE slug='duel-masters')<>1 THEN RAISE EXCEPTION 'game mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM (VALUES (44080::bigint,'dm26ex4-078'),(9163::bigint,'dm22-001'),(17848::bigint,'dm19-s03')) a(canonical_id,official_id) WHERE NOT EXISTS(SELECT 1 FROM public.card_prints p WHERE p.canonical_card_id=a.canonical_id AND p.official_card_id=a.official_id AND p.official_url='https://dm.takaratomy.co.jp/card/detail/?id='||a.official_id AND NOT p.manually_locked AND p.deleted_at IS NULL)) THEN RAISE EXCEPTION 'reviewed official anchor changed'; END IF;
 IF EXISTS(SELECT 1 FROM ex5_stage s LEFT JOIN public.canonical_cards c ON c.id=s.canonical_id WHERE c.id IS NULL OR c.game_id<>(SELECT id FROM public.tcg_games WHERE slug='duel-masters') OR c.manually_locked OR c.deleted_at IS NOT NULL OR c.name IS DISTINCT FROM s.canonical_name OR c.cost IS DISTINCT FROM s.cost OR c.cost_is_infinite IS DISTINCT FROM s.cost_is_infinite OR c.civilizations IS DISTINCT FROM s.civilizations OR c.card_types IS DISTINCT FROM s.card_types OR c.races IS DISTINCT FROM s.races OR c.power_text IS DISTINCT FROM s.power_text OR c.power_value IS DISTINCT FROM s.power_value) THEN RAISE EXCEPTION 'canonical snapshot drift or lock'; END IF;
 IF EXISTS(SELECT 1 FROM public.card_products WHERE product_code='DM26-EX5' AND (game_id<>(SELECT id FROM public.tcg_games WHERE slug='duel-masters') OR product_name IS DISTINCT FROM 'DM26-EX5 デュエル・マスターズTCG デュエマプレイス・コラボパック 「電脳対戦 -WAR OF PLAY''S-」' OR official_url IS DISTINCT FROM 'https://dm.takaratomy.co.jp/product/dm26ex5/' OR release_date IS DISTINCT FROM '2026-11-07'::date OR release_date_precision IS DISTINCT FROM 'day')) THEN RAISE EXCEPTION 'product conflict'; END IF;
 IF EXISTS(SELECT 1 FROM ex5_stage s JOIN public.card_prints p ON p.official_card_id=s.official_card_id OR p.card_number=s.card_number WHERE p.official_card_id IS DISTINCT FROM s.official_card_id OR p.card_number IS DISTINCT FROM s.card_number OR p.canonical_card_id IS DISTINCT FROM s.canonical_id OR p.manually_locked OR p.deleted_at IS NOT NULL OR p.official_url IS DISTINCT FROM s.official_url OR p.product_id IS DISTINCT FROM (SELECT id FROM public.card_products WHERE product_code='DM26-EX5') OR p.card_texts IS DISTINCT FROM s.card_texts OR p.source_metadata IS DISTINCT FROM s.source_metadata) THEN RAISE EXCEPTION 'print conflict'; END IF;
END $$;
INSERT INTO public.card_products(game_id,product_code,product_name,release_date,release_date_precision,official_url)
 SELECT id,'DM26-EX5','DM26-EX5 デュエル・マスターズTCG デュエマプレイス・コラボパック 「電脳対戦 -WAR OF PLAY''S-」','2026-11-07','day','https://dm.takaratomy.co.jp/product/dm26ex5/' FROM public.tcg_games WHERE slug='duel-masters' ON CONFLICT(game_id,product_code) DO NOTHING;
INSERT INTO public.card_prints(canonical_card_id,official_card_id,card_number,product_name,official_url,source_checked_at,product_id,card_texts,source_metadata)
 SELECT s.canonical_id,s.official_card_id,s.card_number,'DM26-EX5 デュエル・マスターズTCG デュエマプレイス・コラボパック 「電脳対戦 -WAR OF PLAY''S-」',s.official_url,s.checked_at,p.id,s.card_texts,s.source_metadata FROM ex5_stage s JOIN public.card_products p ON p.product_code='DM26-EX5'
 WHERE NOT EXISTS(SELECT 1 FROM public.card_prints x WHERE x.official_card_id=s.official_card_id OR x.card_number=s.card_number);
INSERT INTO public.card_search_terms(canonical_card_id,term,normalized_term,term_kind,source,verified,priority)
 SELECT DISTINCT s.canonical_id,s.canonical_name,public.normalize_card_search(s.canonical_name),'official_name','official',true,10 FROM ex5_stage s
 ON CONFLICT(canonical_card_id,normalized_term,term_kind) DO NOTHING;


