"verified":false}}]}]'::jsonb) AS r(name text,official_id text,official_url text,card_number text,cost smallint,cost_is_infinite boolean,civilizations text[],card_types text[],races text[],power_text text,power_value integer,card_texts text[],checked_at timestamptz,faces jsonb);
DO $$ BEGIN
 IF (SELECT count(*) FROM public.tcg_games WHERE slug='duel-masters')<>1 THEN RAISE EXCEPTION 'game mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM ex5_new s JOIN public.canonical_cards c ON c.game_id=(SELECT id FROM tcg_games WHERE slug='duel-masters') AND public.normalize_card_search(c.name)=public.normalize_card_search(s.name) WHERE c.name<>s.name OR c.deleted_at IS NOT NULL OR c.manually_locked OR c.metadata_provenance->'ex5_create' IS DISTINCT FROM jsonb_build_object('verified',true,'source','official_catalog') OR c.cost IS DISTINCT FROM s.cost OR c.cost_is_infinite IS DISTINCT FROM s.cost_is_infinite OR c.civilizations IS DISTINCT FROM s.civilizations OR c.card_types IS DISTINCT FROM s.card_types OR c.races IS DISTINCT FROM s.races OR c.power_text IS DISTINCT FROM s.power_text OR c.power_value IS DISTINCT FROM s.power_value) THEN RAISE EXCEPTION 'canonical collision'; END IF;
 IF EXISTS(SELECT 1 FROM ex5_new s JOIN public.canonical_cards c ON c.game_id=(SELECT id FROM tcg_games WHERE slug='duel-masters') AND c.name<>s.name WHERE EXISTS(SELECT 1 FROM unnest(c.aliases) a WHERE public.normalize_card_search(a)=public.normalize_card_search(s.name)) OR EXISTS(SELECT 1 FROM card_search_terms t WHERE t.canonical_card_id=c.id AND t.normalized_term=public.normalize_card_search(s.name))) THEN RAISE EXCEPTION 'alias collision'; END IF;
 IF EXISTS(SELECT 1 FROM ex5_new s JOIN public.card_prints p ON p.official_card_id=s.official_id OR p.card_number=s.card_number LEFT JOIN canonical_cards c ON c.id=p.canonical_card_id WHERE p.official_card_id IS DISTINCT FROM s.official_id OR p.card_number IS DISTINCT FROM s.card_number OR c.name IS DISTINCT FROM s.name OR p.deleted_at IS NOT NULL OR p.manually_locked OR p.official_url IS DISTINCT FROM s.official_url OR p.card_texts IS DISTINCT FROM s.card_texts OR p.product_id IS DISTINCT FROM (SELECT id FROM card_products WHERE product_code='DM26-EX5') OR p.source_metadata IS DISTINCT FROM jsonb_build_object('official_catalog',jsonb_build_object('verified',true,'official_url',s.official_url,'checked_at',s.checked_at,'faces',s.faces))) THEN RAISE EXCEPTION 'print collision'; END IF;
 IF EXISTS(SELECT 1 FROM card_products WHERE product_code='DM26-EX5' AND (product_name IS DISTINCT FROM 'DM26-EX5 デュエル・マスターズTCG デュエマプレイス・コラボパック 「電脳対戦 -WAR OF PLAY''S-」' OR official_url IS DISTINCT FROM 'https://dm.takaratomy.co.jp/product/dm26ex5/' OR release_date IS DISTINCT FROM '2026-11-07'::date OR game_id<>(SELECT id FROM tcg_games WHERE slug='duel-masters'))) THEN RAISE EXCEPTION 'product conflict'; END IF;
END $$;
INSERT INTO card_products(game_id,product_code,product_name,release_date,release_date_precision,official_url) SELECT id,'DM26-EX5','DM26-EX5 デュエル・マスターズTCG デュエマプレイス・コラボパック 「電脳対戦 -WAR OF PLAY''S-」','2026-11-07','day','https://dm.takaratomy.co.jp/product/dm26ex5/' FROM tcg_games WHERE slug='duel-masters' ON CONFLICT(game_id,product_code) DO NOTHING;
INSERT INTO canonical_cards(game_id,name,source_name,cost,cost_is_infinite,civilizations,card_types,races,power_text,power_value,metadata_provenance)
 SELECT DISTINCT ON (s.name) g.id,s.name,s.name,s.cost,s.cost_is_infinite,s.civilizations,s.card_types,s.races,s.power_text,s.power_value,jsonb_build_object('ex5_create',jsonb_build_object('verified',true,'source','official_catalog')) FROM ex5_new s CROSS JOIN tcg_games g WHERE g.slug='duel-masters' AND NOT EXISTS(SELECT 1 FROM canonical_cards c WHERE c.game_id=g.id AND c.name=s.name) ORDER BY s.name;
INSERT INTO card_prints(canonical_card_id,official_card_id,official_url,card_number,product_name,source_checked_at,product_id,card_texts,source_metadata)
 SELECT c.id,s.official_id,s.official_url,s.card_number,'DM26-EX5 デュエル・マスターズTCG デュエマプレイス・コラボパック 「電脳対戦 -WAR OF PLAY''S-」',s.checked_at,p.id,s.card_texts,jsonb_build_object('official_catalog',jsonb_build_object('verified',true,'official_url',s.official_url,'checked_at',s.checked_at,'faces',s.faces)) FROM ex5_new s JOIN canonical_cards c ON c.name=s.name AND c.game_id=(SELECT id FROM tcg_games WHERE slug='duel-masters') JOIN card_products p ON p.product_code='DM26-EX5' WHERE NOT EXISTS(SELECT 1 FROM card_prints x WHERE x.official_card_id=s.official_id OR x.card_number=s.card_number);
INSERT INTO card_search_terms(canonical_card_id,term,normalized_term,term_kind,source,verified,priority) SELECT DISTINCT c.id,s.name,public.normalize_card_search(s.name),'official_name','official',true,10 FROM ex5_new s JOIN canonical_cards c ON c.name=s.name AND c.game_id=(SELECT id FROM tcg_games WHERE slug='duel-masters') ON CONFLICT(canonical_card_id,normalized_term,term_kind) DO NOTHING;

DO $$ BEGIN IF EXISTS(SELECT official_card_id FROM public.card_prints WHERE official_card_id LIKE 'dm26ex5-%' GROUP BY official_card_id HAVING count(*)>1) OR (SELECT count(*) FROM public.card_prints WHERE official_card_id LIKE 'dm26ex5-%' AND deleted_at IS NULL)<>115 THEN RAISE EXCEPTION 'EX5 final count or duplicate mismatch'; END IF; END $$;
COMMIT;
